import{_ as c,C as d,o as s,c as i,a2 as a,E as e}from"./chunks/framework.TaNiW7i8.js";const w=JSON.parse('{"title":"Write to the memory","description":"","frontmatter":{"title":"Write to the memory"},"headers":[],"relativePath":"en/agent/ecrire.md","filePath":"en/agent/ecrire.md"}'),h={name:"en/agent/ecrire.md"};function l(m,t,p,f,g,u){const o=d("AskExample"),n=d("Ask"),r=d("Capture");return s(),i("div",null,[t[0]||(t[0]=a('<h1 id="write-to-the-memory" tabindex="-1">Write to the memory <a class="header-anchor" href="#write-to-the-memory" aria-label="Permalink to &quot;Write to the memory&quot;">​</a></h1><p>This journey brings a fact, a principle, a goal, a person or a document into the memory: the agent creates a <strong>note</strong> (an &quot;atom&quot;) in the right zone. For what the session itself leaves, see <a href="/Kessho/en/agent/archiver.html">Archive a session</a>.</p><h2 id="what-you-ask-the-agent" tabindex="-1">What you ask the agent <a class="header-anchor" href="#what-you-ask-the-agent" aria-label="Permalink to &quot;What you ask the agent&quot;">​</a></h2>',3)),e(o,{tool:"mem_note"}),e(o,{tool:"mem_principle"}),e(o,{tool:"mem_goal"}),e(o,{tool:"mem_person"}),e(o,{tool:"mem_doc"}),e(n,{say:"Set this aside, I'll sort it later: remember to ask for a quote for the LED rail.",verb:"mem",family:"ingestion",args:'{"content":"Remember to ask for a quote for the LED rail.","hint":"idea"}'}),t[1]||(t[1]=a('<p>When you do not say what kind of content it is (&quot;note this&quot;, &quot;keep that&quot;), the agent may use <code>mem</code>, which drops it in the inbox; when you do (&quot;remember this principle&quot;), it calls the tool of that type.</p><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><p>Each tool <strong>writes a new note</strong>:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Where it lands</th><th>Required</th><th>Good to know</th></tr></thead><tbody><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem"><code>mem</code></a></td><td><code>00-inbox/</code></td><td><code>content</code></td><td><code>hint</code> steers the later filing: <code>note</code>, <code>principle</code>, <code>goal</code>, <code>person</code> or <code>idea</code>.</td></tr><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem-note"><code>mem_note</code></a></td><td><code>20-knowledge/</code></td><td><code>title</code>, <code>content</code></td><td><code>title</code> serves as the name.</td></tr><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem-principle"><code>mem_principle</code></a></td><td><code>40-principles/{scope}/</code></td><td><code>title</code>, <code>content</code></td><td><code>force</code>: <code>red-line</code>, <code>heuristic</code> (default), <code>value</code> or <code>action-rule</code>.</td></tr><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem-goal"><code>mem_goal</code></a></td><td><code>50-goals/{horizon}/</code></td><td><code>title</code></td><td><code>horizon</code>: <code>short</code> (default), <code>medium</code> or <code>long</code>; <code>status</code>: <code>open</code> (default), <code>in-progress</code>, <code>done</code> or <code>abandoned</code>; <code>deadline</code> as YYYY-MM-DD.</td></tr><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem-person"><code>mem_person</code></a></td><td><code>60-people/{relation}/</code></td><td><code>name</code></td><td><code>relation</code>: <code>colleague</code> (default), <code>client</code>, <code>friend</code>, <code>family</code> or <code>other</code>. The card is marked <strong>sensitive</strong> by default (<code>sensitive</code>).</td></tr><tr><td><a href="/Kessho/en/reference/mcp/ingestion.html#mem-doc"><code>mem_doc</code></a></td><td><code>00-inbox/</code></td><td><code>path</code> (absolute)</td><td>One local document per call: Markdown, text, PDF, DOCX, XLSX, PPTX, HTML or CSV.</td></tr></tbody></table><p>All except <code>mem</code> accept <code>project</code> (the project it belongs to) and <code>scope</code>: <code>work</code> (default), <code>personal</code> or <code>all</code>.</p><p><strong>None of these writes overwrites an existing note.</strong> If the name is already taken, the server picks another by adding a suffix (<code>-2</code>, <code>-3</code>…); the answer gives the path actually written. The agent therefore does not have to check first whether the note exists. When the write lands in a cross-cutting zone, that zone&#39;s <code>index.md</code> is regenerated.</p><p>Other tools write notes, with their own rule:</p><ul><li><a href="/Kessho/en/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a>, in full mode, creates the notes of <code>derive</code>; a name already taken makes it <strong>refuse</strong> the whole archive (see <a href="/Kessho/en/agent/archiver.html">Archive a session</a>).</li><li><a href="/Kessho/en/reference/mcp/ingestion.html#mem-codebase"><code>mem_codebase</code></a> records in a project&#39;s map a fact that the code does not say by itself (<code>fact</code>, <code>body</code>, <code>project</code>). It asks for the files the fact describes (<code>describes</code>, paths relative to the repository, which must exist) or, failing that, <code>unmeasurable_because</code>, the reason it attaches to no file; with neither, the write is refused. The catalog advises consulting <a href="/Kessho/en/reference/mcp/maintenance.html#mem-codebase-scan"><code>mem_codebase_scan</code></a> first.</li></ul><p>Correcting an existing note is not the job of these tools: renaming, moving, attaching or removing is done with those of <a href="/Kessho/en/agent/entretenir.html">Maintain the memory</a>.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2>',10)),e(r,{name:"zone-liste",alt:"The Knowledge zone as a list, filtered on “This year”: one row per note, with its type and project."}),t[2]||(t[2]=a('<p>The written note appears in its zone, here <strong>Knowledge</strong> (<code>20-knowledge</code>): one row per note, with its type and its project (see <a href="/Kessho/en/guide/zones.html">Zones</a>). The freshness indicator lights up as soon as the agent writes, and <strong>Reload</strong> refreshes the list. To open the note and read or edit it, see <a href="/Kessho/en/guide/atom.html">Atom and editor</a>.</p><p>You can also create a note yourself, with <strong>New</strong> in the zone header: the agent is not needed.</p>',2))])}const y=c(h,[["render",l]]);export{w as __pageData,y as default};
